SELECT id, user_id, device_id, measure_time, total_cholesterol, triglycerides, hdl, ldl FROM t_blood_lipid  AND id = #{id}
 AND user_id = #{userId}
 AND device_id = #{deviceId}
 AND measure_time = #{measureTime}
 AND total_cholesterol = #{totalCholesterol}
 AND triglycerides = #{triglycerides}
 AND hdl = #{hdl}
 AND ldl = #{ldl} ORDER BY id DESC
